function wheelRewardLabel(reward){return state.language==='en'?reward.labelEn:reward.labelHu}
function wheelRewardShort(reward){return state.language==='en'?reward.shortEn:reward.shortHu}
function renderWheelPrizes(){const list=document.querySelector('#wheelPrizeList'),previewIcon=document.querySelector('#rewardPreviewIcon'),previewLabel=document.querySelector('#rewardPreviewLabel');if(!list||!previewIcon||!previewLabel)return;const nextIndex=workshop.wheelSpins%wheelRewards.length,next=wheelRewards[nextIndex],key=`${state.language}-${nextIndex}`;previewIcon.textContent=next.icon;previewLabel.textContent=wheelRewardLabel(next);if(list.dataset.rewardKey===key)return;list.dataset.rewardKey=key;list.innerHTML=wheelRewards.map((reward,index)=>`<div class="reward-prize ${index===nextIndex?'next':''}"><span>${reward.icon}</span><strong>${wheelRewardLabel(reward)}</strong>${index===nextIndex?`<small>${repairText('KÖVETKEZŐ','NEXT')}</small>`:''}</div>`).join('')}
function updateWheel(){const button=document.querySelector('#spinWheel'),label=document.querySelector('#wheelCooldown');if(!button||wheelBusy)return;const next=wheelRewards[workshop.wheelSpins%wheelRewards.length],left=Math.max(0,workshop.wheelReadyAt-Date.now());button.disabled=left>0;renderWheelPrizes();if(left>0){const total=Math.ceil(left/1000),m=String(Math.floor(total/60)).padStart(2,'0'),s=String(total%60).padStart(2,'0');label.textContent=`${repairText('Következő bónusz','Next bonus')}: ${m}:${s}`}else label.textContent=`${repairText('Következő bónusz','Next bonus')}: ${wheelRewardLabel(next)}`}
let rewardAudioContext=null,rewardCelebrationTimer=0;
function prepareRewardAudio(){try{const AudioCtx=window.AudioContext||window.webkitAudioContext;if(!AudioCtx)return null;rewardAudioContext??=new AudioCtx();if(rewardAudioContext.state==='suspended')rewardAudioContext.resume();return rewardAudioContext}catch{return null}}
function playRewardSound(context){if(!context)return;try{const now=context.currentTime,master=context.createGain();master.gain.setValueAtTime(.0001,now);master.gain.exponentialRampToValueAtTime(.055,now+.035);master.gain.exponentialRampToValueAtTime(.0001,now+.82);master.connect(context.destination);[523.25,659.25,783.99,1046.5].forEach((frequency,index)=>{const oscillator=context.createOscillator(),gain=context.createGain(),start=now+index*.085;oscillator.type=index<2?'triangle':'sine';oscillator.frequency.setValueAtTime(frequency,start);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(index===3?.24:.34,start+.025);gain.gain.exponentialRampToValueAtTime(.0001,start+.38);oscillator.connect(gain);gain.connect(master);oscillator.start(start);oscillator.stop(start+.42)})}catch{}}
function showRewardCelebration(reward){const layer=document.querySelector('#rewardCelebration'),confetti=document.querySelector('#rewardConfetti'),icon=document.querySelector('#rewardCelebrationIcon'),title=document.querySelector('#rewardCelebrationTitle'),text=document.querySelector('#rewardCelebrationText');if(!layer||!confetti||!icon||!title||!text)return;clearTimeout(rewardCelebrationTimer);icon.textContent=reward.icon;title.textContent=repairText('Jutalom megszerezve!','Reward unlocked!');text.textContent=wheelRewardLabel(reward);confetti.innerHTML='';const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches,count=reduced?0:(window.innerWidth<600?44:72),colors=['#ff4b8b','#58e5ff','#ffe171','#9c6cff','#65edae','#ff805c'];for(let index=0;index<count;index++){const piece=document.createElement('i'),angle=(Math.PI*2*index/count)+(Math.random()*.18-.09),distance=170+Math.random()*(window.innerWidth<600?190:360);piece.style.setProperty('--confetti-color',colors[index%colors.length]);piece.style.setProperty('--confetti-x',`${Math.cos(angle)*distance}px`);piece.style.setProperty('--confetti-y',`${Math.sin(angle)*distance+100+Math.random()*150}px`);piece.style.setProperty('--confetti-rotate',`${360+Math.random()*720}deg`);piece.style.setProperty('--confetti-delay',`${Math.random()*.12}s`);confetti.appendChild(piece)}layer.classList.remove('show');void layer.offsetWidth;layer.classList.add('show');layer.setAttribute('aria-hidden','false');rewardCelebrationTimer=setTimeout(()=>{layer.classList.remove('show');layer.setAttribute('aria-hidden','true');setTimeout(()=>{confetti.innerHTML=''},250)},3500)}
function spinWheel(){if(wheelBusy||Date.now()<workshop.wheelReadyAt)return;wheelBusy=true;const resultIndex=workshop.wheelSpins%wheelRewards.length,result=wheelRewards[resultIndex],button=document.querySelector('#spinWheel'),terminal=document.querySelector('#prizeWheel'),scan=document.querySelector('#rewardScanProgress'),audioContext=prepareRewardAudio();if(!button||!terminal||!scan){wheelBusy=false;return}button.disabled=true;document.querySelector('#wheelResult').textContent=repairText('A tech jutalom aktiválódik…','The tech reward is activating…');let completed=false,fallback=0;const finishActivation=()=>{if(completed)return;completed=true;clearTimeout(fallback);scan.removeEventListener('animationend',onAnimationEnd);result.run();workshop.wheelReadyAt=Date.now()+900000;workshop.wheelSpins++;wheelBusy=false;terminal.classList.remove('charging');scan.classList.remove('running');save();saveWorkshop();renderWheelPrizes();document.querySelector('#wheelResult').textContent=`${repairText('Jutalmad','Your reward')}: ${wheelRewardLabel(result)}`;showRewardCelebration(result);playRewardSound(audioContext);toast(`${repairText('Tech bónusz','Tech bonus')}: ${wheelRewardLabel(result)}`)};const onAnimationEnd=event=>{if(event.target===scan&&event.animationName==='vmRewardScan')finishActivation()};scan.addEventListener('animationend',onAnimationEnd);scan.classList.remove('running');void scan.offsetWidth;terminal.classList.add('charging');scan.classList.add('running');if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)setTimeout(finishActivation,120);else fallback=setTimeout(finishActivation,4600)}
document.addEventListener('click',e=>{if(e.target.closest('[data-view="workshop"]'))renderWorkshop();if(e.target.closest('[data-view="team"]'))renderEmployees();if(e.target.closest('[data-view="store"]'))renderStore();const salvage=e.target.closest('.salvage-buy');if(salvage)buySalvage(salvage.dataset.blueprint);const part=e.target.closest('.quality-buy');if(part)buyPart(part.dataset.part,part.dataset.quality);const quality=e.target.closest('.quality-select');if(quality)setProjectQuality(quality.dataset.project,quality.dataset.projectQuality);const diagnose=e.target.closest('.diagnose');if(diagnose)startDiagnostic(diagnose.dataset.project);const assemble=e.target.closest('.assemble');if(assemble)startAssembly(assemble.dataset.project);const piece=e.target.closest('.assembly-part');if(piece)chooseAssembly(piece.dataset.assemblyPart);const node=e.target.closest('.circuit-node');if(node)circuitClick(node);const print=e.target.closest('.start-print');if(print)startPrint(print.dataset.print);if(e.target.closest('.buy-printer'))buyPrinter();const list=e.target.closest('.list-market');if(list)listOnMarket(Number(list.dataset.finished));const deliver=e.target.closest('.deliver-order');if(deliver)deliverOrder(Number(deliver.dataset.finished));if(e.target.closest('.accept-offer'))acceptOffer();if(e.target.closest('.decline-offer'))declineOffer();const hire=e.target.closest('.hire-employee');if(hire)hireEmployee(hire.dataset.employee);if(e.target.closest('.buy-store'))buyStore();const upgrade=e.target.closest('.buy-store-upgrade');if(upgrade)buyStoreUpgrade(upgrade.dataset.upgrade);const storeHire=e.target.closest('.hire-store-staff');if(storeHire)hireStoreStaff(storeHire.dataset.storeStaff)});
document.addEventListener('click',e=>{if(e.target.closest('.hire-repair-employee'))hireRepairEmployee();if(e.target.closest('.start-repair-employee'))startRepairEmployee();if(e.target.closest('.start-employee-assembly'))startEmployeeAssembly();const bid=e.target.closest('.accept-bid');if(bid)acceptMarketBid(bid.dataset.listing)});
function commerceTick(){if(!workshop.activeOrder){const now=Date.now();if(workshop.customerOffer&&now>=workshop.offerExpiresAt){workshop.customerOffer=null;generateCustomerOffer();localStorage.setItem('voltmarket-workshop',JSON.stringify(workshop))}else if(!workshop.customerOffer&&now>=workshop.offerExpiresAt){generateCustomerOffer();localStorage.setItem('voltmarket-workshop',JSON.stringify(workshop))}}settleMarket();employeeTick();storeTick();renderCustomerMarket();renderEmployees();renderStore();updateWheel()}
document.querySelector('#typingInput').addEventListener('input',typingInput);document.querySelector('#closeGame').onclick=closeGame;document.querySelector('#gameModal').addEventListener('click',e=>{if(e.target.id==='gameModal')closeGame()});document.querySelector('#spinWheel').addEventListener('click',spinWheel);document.querySelector('#resetButton').addEventListener('click',()=>{setTimeout(()=>{if(state.balance===150000&&state.level===1&&state.history.length===0){workshop={...emptyWorkshop,parts:{},projects:[],finished:[],marketListings:[],employees:[],employeeTimers:{},storeUpgrades:[],storeStaff:[],nextId:1};saveWorkshop()}},0)});if(!workshop.activeOrder&&!workshop.customerOffer&&Date.now()>=workshop.offerExpiresAt)generateCustomerOffer();localStorage.setItem('voltmarket-workshop',JSON.stringify(workshop));setInterval(commerceTick,1000);updateWheel();renderWorkshop();renderEmployees();renderStore();
